<script lang="ts">
  import type { PersonView, SiteView, Tagline } from '$lib/api/types'

  import Markdown from '$lib/app/markdown/Markdown.svelte'
  import { settings } from '$lib/app/settings.svelte'
  import { userLink } from '$lib/app/util.svelte'
  import EntityHeader from '$lib/ui/generic/EntityHeader.svelte'
  import ItemList from '$lib/ui/generic/ItemList.svelte'
  import LabelStat from '$lib/ui/info/LabelStat.svelte'
  import EndPlaceholder from '$lib/ui/layout/EndPlaceholder.svelte'
  import SidebarButton from '$lib/ui/sidebar/SidebarButton.svelte'
  import { Badge, Expandable, Popover } from 'mono-svelte'
  import {
    BuildingOffice,
    Icon,
    Newspaper,
    ServerStack,
  } from 'svelte-hero-icons/dist'
  import type { ClassValue, HTMLAttributes } from 'svelte/elements'

  interface Props extends HTMLAttributes<HTMLDivElement> {
    site: SiteView
    taglines?: Tagline[]
    admins?: PersonView[]
    version?: string
    class?: ClassValue
  }

  let { site, taglines, admins, version, class: clazz = '' }: Props = $props()
</script>

<aside
  class={[
    'w-full text-slate-600 dark:text-zinc-400 flex flex-col gap-4 text-sm',
    clazz,
  ]}
>
  <EntityHeader
    name={site.site.name}
    avatar={site.site.icon}
    banner={site.site.banner || null}
    compact="always"
    avatarCircle={false}
  />
  <div class="flex flex-col gap-1">
    {#if taglines && taglines.length > 0}
      <Markdown
        class="px-3"
        source={taglines[Math.floor(Math.random() * taglines.length)].content}
      />
    {/if}

    <EndPlaceholder size="xs" margin="sm">
      Server info
    </EndPlaceholder>
    <SidebarButton
      href="/modlog"
      label=Modlog
      icon={Newspaper}
    />
    <SidebarButton
      href="/legal"
      label=Legal
      icon={BuildingOffice}
    />
    <SidebarButton
      href="/instances"
      label="Linked servers"
      icon={ServerStack}
    />

    <EndPlaceholder size="xs" margin="sm">
      Statistics
    </EndPlaceholder>
    <div class="flex flex-row gap-4 flex-wrap px-3">
      <LabelStat
        label=Users
        content={site.counts.users.toString()}
        formatted
      />
      <LabelStat
        label=Posts
        content={site.counts.posts.toString()}
        formatted
      />
      <LabelStat
        label=Comments
        content={site.counts.comments.toString()}
        formatted
      />
      <Popover openOnHover placement="bottom-end">
        {#snippet target(attachment)}
          <button class="text-left cursor-pointer" {@attach attachment}>
            <LabelStat
              label="Active Today"
              content={site.counts.users_active_day.toString()}
              formatted
            />
          </button>
        {/snippet}
        <div class="flex flex-row gap-4 flex-wrap px-3">
          <LabelStat
            label="Past week"
            content={site.counts.users_active_week.toString()}
            formatted
          />
          <LabelStat
            label="Past month"
            content={site.counts.users_active_month.toString()}
            formatted
          />
          <LabelStat
            label="6 months"
            content={site.counts.users_active_half_year.toString()}
            formatted
          />
        </div>
      </Popover>
      <LabelStat
        label=Communities
        content={site.counts.communities.toString()}
        formatted
      />
    </div>

    <EndPlaceholder size="xs" margin="sm">
      Info
    </EndPlaceholder>
    <div class="space-y-3 px-1.5 text-sm">
      <Expandable bind:open={settings.expand.about}>
        {#snippet title()}
          <span class="flex items-center gap-1 py-1 px-2 w-full">
            About
          </span>
        {/snippet}
        <Markdown source={site.site.description} />
        <div class="my-4"></div>
        <Markdown source={site.site.sidebar} />

        {#if version}
          <div class="w-max">
            <Badge label="Lemmy version">
              <Icon src={ServerStack} micro size="14" />
              {version}
            </Badge>
          </div>
        {/if}
      </Expandable>

      {#if admins}
        <Expandable bind:open={settings.expand.team}>
          {#snippet title()}
            <span class="flex items-center gap-1 py-1 px-2 w-full">
              Admins
            </span>
          {/snippet}
          <ItemList
            items={admins.map((i) => ({
              id: i.person.id,
              name: i.person.display_name || i.person.name,
              url: userLink(i.person),
              avatar: i.person.avatar,
              instance: new URL(i.person.actor_id).hostname,
            }))}
          />
        </Expandable>
      {/if}
    </div>
  </div>
</aside>
